llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, has only 15% oral bioavailability in humans, below the 20% threshold, showing that a long-chain ester prodrug can be poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "DEHP, a highly lipophilic diester plasticizer, has about 25% oral bioavailability in human volunteers, only marginally above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a fatty acid ester prodrug, has an absolute oral bioavailability of 85 ± 15% in children, demonstrating that some lipophilic ester prodrugs are well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug, has an absolute oral bioavailability of 66% in humans.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Capecitabine, an oral prodrug, has a bioavailability of almost 100% in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a recognized locally acting gastrointestinal lipase inhibitor with negligible systemic absorption. Although many ester prodrugs in the evidence set are well absorbed, the only directly relevant low-bioavailability ester prodrug comparator (laninamivir octanoate, 15%) and the established pharmacology of orlistat support F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for orlistat is present in the provided records.",
    "Most high-bioavailability comparators are well-absorbed ester prodrugs or plasticizers without the beta-lactone lipase-inhibitor scaffold.",
    "The only low-bioavailability comparator is not a beta-lactone and is used as an inhaled prodrug, limiting structural transferability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C31"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lipophilic ester prodrugs"
    }
  ],
  "revision_action": "initial"
}

